const L = localized;
const S = section;

function makeArticle({ slug, category, areas, title, summary, keywords, plan, permissions, prerequisites, navigation, expected, problems, sections, related = [], sourceFiles, sourceRoutes }) {
  const resolvedCategory = category === 'troubleshooting'
    ? ({ 'AI Assistants': 'ai-assistants', 'Web Chatbot': 'web-chatbot', 'WhatsApp AI': 'whatsapp-ai' }[areas[0]] || category)
    : category;
  return Object.freeze({
    slug, category: resolvedCategory, coverageAreas: areas, title, summary, keywords, plan, permissions, prerequisites, navigation, expected, problems, sections: [...sections, S(L('Troubleshooting', 'Sorun giderme', 'استكشاف المشكلات'), problems)], related,
    verification: { status: 'Published', verifiedOn: AUDIT_DATE, sourceFiles, sourceRoutes, reviewTriggers: ['dashboard route or navigation label changes', 'control or permission changes', 'plan entitlement changes'] },
  });
}

